// Procedural cartoon cricketer portraits (original artwork, generated by code).
// characterSvg(spec) -> SVG string, 512x512, transparent background.
const OUT = "#1d1530";
const SW = 7;

const clamp = (v) => Math.max(0, Math.min(255, v));
export const adj = (hex, amt) => {
  const n = parseInt(hex.slice(1), 16);
  const f = (c) => clamp(Math.round(amt >= 0 ? c + (255 - c) * amt : c * (1 + amt)));
  const r = f(n >> 16), g = f((n >> 8) & 255), b = f(n & 255);
  return `#${((1 << 24) | (r << 16) | (g << 8) | b).toString(16).slice(1)}`;
};

const headPath = (cx, cy, w, h, chin) => {
  const t = cy - h / 2, b = cy + h / 2, r = cx + w / 2, l = cx - w / 2, cw = w * chin;
  return `M${cx},${t} C${cx + w * 0.3},${t} ${r},${cy - h * 0.28} ${r},${cy - h * 0.02} C${r},${cy + h * 0.22} ${cx + cw + w * 0.12},${b - h * 0.03} ${cx + cw},${b - h * 0.01} Q${cx},${b + h * 0.035} ${cx - cw},${b - h * 0.01} C${cx - cw - w * 0.12},${b - h * 0.03} ${l},${cy + h * 0.22} ${l},${cy - h * 0.02} C${l},${cy - h * 0.28} ${cx - w * 0.3},${t} ${cx},${t} Z`;
};

const st = (extra = "") =>
  `stroke="${OUT}" ${extra.includes("stroke-width") ? "" : `stroke-width="${SW}"`} stroke-linejoin="round" stroke-linecap="round" ${extra}`;

// ---- jersey ----------------------------------------------------------------
function jersey(s) {
  const { jersey: c, trim: t, collar } = s;
  const body = `M30,520 C40,430 110,392 256,386 C402,392 472,430 482,520 Z`;
  let out = `<path d="${body}" fill="${c}" ${st()}/>`;
  out += `<path d="M44,478 C56,440 100,414 150,402 L130,520 L40,520Z" fill="${t}" opacity=".9"/>`; // sleeve panel
  out += `<path d="M468,478 C456,440 412,414 362,402 L382,520 L472,520Z" fill="${t}" opacity=".9"/>`;
  out += `<path d="M250,392 L262,520" stroke="${adj(c, -0.25)}" stroke-width="5" opacity=".0"/>`;
  out += `<path d="M120,450 C190,436 322,436 392,450" fill="none" stroke="${t}" stroke-width="14" opacity=".85"/>`;
  if (collar === "v") out += `<path d="M206,388 L256,452 L306,388 Z" fill="${adj(s.skin, -0.12)}" ${st()}/><path d="M196,384 L256,466 L316,384" fill="none" stroke="${t}" stroke-width="12" stroke-linejoin="round" stroke-linecap="round"/>`;
  else if (collar === "polo") out += `<path d="M212,386 L256,424 L300,386 Z" fill="${adj(s.skin, -0.12)}" ${st()}/><path d="M196,380 L240,426 L222,440 L180,396Z" fill="${t}" ${st('stroke-width="5"')}/><path d="M316,380 L272,426 L290,440 L332,396Z" fill="${t}" ${st('stroke-width="5"')}/>`;
  else out += `<path d="M204,388 Q256,436 308,388" fill="${adj(s.skin, -0.12)}" ${st()}/><path d="M198,386 Q256,446 314,386" fill="none" stroke="${t}" stroke-width="12" stroke-linecap="round"/>`;
  return out;
}

// ---- eyes ------------------------------------------------------------------
function eye(style, x, y, side, s) {
  const look = s.look * 5;
  const white = "#fff";
  switch (style) {
    case "wide":
      return `<ellipse cx="${x}" cy="${y}" rx="22" ry="25" fill="${white}" ${st('stroke-width="5"')}/><circle cx="${x + look}" cy="${y}" r="6" fill="${OUT}"/>`;
    case "happy":
      return `<path d="M${x - 17},${y + 6} Q${x},${y - 18} ${x + 17},${y + 6}" fill="none" ${st('stroke-width="7"')}/>`;
    case "smug":
      return `<ellipse cx="${x}" cy="${y}" rx="17" ry="17" fill="${white}" ${st('stroke-width="5"')}/><circle cx="${x + look}" cy="${y + 3}" r="8" fill="${OUT}"/><path d="M${x - 19},${y - 1} L${x + 19},${y - 1} L${x + 19},${y - 20} L${x - 19},${y - 20}Z" fill="${adj(s.skin, -0.05)}" opacity="0"/><path d="M${x - 18},${y - 3} Q${x},${y - 12} ${x + 18},${y - 3}" fill="none" ${st('stroke-width="6"')}/>`;
    case "sleepy":
      return `<ellipse cx="${x}" cy="${y + 3}" rx="17" ry="12" fill="${white}" ${st('stroke-width="5"')}/><circle cx="${x + look}" cy="${y + 6}" r="6" fill="${OUT}"/><path d="M${x - 18},${y + 1} Q${x},${y - 6} ${x + 18},${y + 1}" fill="${adj(s.skin, -0.1)}" ${st('stroke-width="6"')}/>`;
    case "angry":
      return `<ellipse cx="${x}" cy="${y + 2}" rx="17" ry="17" fill="${white}" ${st('stroke-width="5"')}/><circle cx="${x + look}" cy="${y + 4}" r="8" fill="${OUT}"/><path d="M${x - 20},${y - (side < 0 ? 16 : 2)} L${x + 20},${y - (side < 0 ? 2 : 16)} L${x + 20},${y - 24} L${x - 20},${y - 24} Z" fill="${s.skin}" stroke="${OUT}" stroke-width="5" stroke-linejoin="round"/>`;
    case "crazy": {
      const big = side < 0;
      const rx = big ? 24 : 14;
      return `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${rx + 3}" fill="${white}" ${st('stroke-width="5"')}/><circle cx="${x + (big ? -4 : 3)}" cy="${y + (big ? 4 : -2)}" r="${big ? 5 : 4}" fill="${OUT}"/>`;
    }
    case "wink":
      return side < 0
        ? `<ellipse cx="${x}" cy="${y}" rx="17" ry="19" fill="${white}" ${st('stroke-width="5"')}/><circle cx="${x + look}" cy="${y}" r="8" fill="${OUT}"/><circle cx="${x + look + 3}" cy="${y - 3}" r="2.5" fill="#fff"/>`
        : `<path d="M${x - 16},${y + 2} Q${x},${y - 12} ${x + 16},${y + 2}" fill="none" ${st('stroke-width="7"')}/>`;
    default:
      return `<ellipse cx="${x}" cy="${y}" rx="17" ry="19" fill="${white}" ${st('stroke-width="5"')}/><circle cx="${x + look}" cy="${y + 1}" r="8" fill="${OUT}"/><circle cx="${x + look + 3}" cy="${y - 3}" r="2.5" fill="#fff"/>`;
  }
}

function brows(style, cx, y, dx, color) {
  const l = cx - dx, r = cx + dx;
  const fillStroke = `fill="${color}" ${st('stroke-width="4"')}`;
  switch (style) {
    case "angry":
      return `<path d="M${l - 24},${y - 14} L${l + 22},${y + 6} L${l + 20},${y - 8} L${l - 22},${y - 28}Z" ${fillStroke}/><path d="M${r + 24},${y - 14} L${r - 22},${y + 6} L${r - 20},${y - 8} L${r + 22},${y - 28}Z" ${fillStroke}/>`;
    case "raised":
      return `<path d="M${l - 22},${y - 8} Q${l},${y - 32} ${l + 22},${y - 8}" fill="none" stroke="${color}" stroke-width="9" stroke-linecap="round"/><path d="M${r - 22},${y - 8} Q${r},${y - 32} ${r + 22},${y - 8}" fill="none" stroke="${color}" stroke-width="9" stroke-linecap="round"/>`;
    case "cheeky":
      return `<path d="M${l - 22},${y - 14} Q${l},${y - 40} ${l + 22},${y - 16}" fill="none" stroke="${color}" stroke-width="10" stroke-linecap="round"/><path d="M${r - 22},${y + 2} L${r + 22},${y - 6}" stroke="${color}" stroke-width="10" stroke-linecap="round"/>`;
    case "bushy":
      return `<path d="M${l - 26},${y - 6} Q${l},${y - 26} ${l + 24},${y - 6} Q${l},${y - 12} ${l - 26},${y - 6}Z" ${fillStroke}/><path d="M${r - 24},${y - 6} Q${r},${y - 26} ${r + 26},${y - 6} Q${r},${y - 12} ${r - 24},${y - 6}Z" ${fillStroke}/>`;
    case "worried":
      return `<path d="M${l - 24},${y + 2} L${l + 22},${y - 18}" stroke="${color}" stroke-width="9" stroke-linecap="round"/><path d="M${r + 24},${y + 2} L${r - 22},${y - 18}" stroke="${color}" stroke-width="9" stroke-linecap="round"/>`;
    case "unibrow":
      return `<path d="M${l - 26},${y - 8} Q${l},${y - 28} ${cx},${y - 8} Q${r},${y - 28} ${r + 26},${y - 8} Q${r},${y - 4} ${cx},${y + 4} Q${l},${y - 4} ${l - 26},${y - 8}Z" ${fillStroke}/>`;
    default:
      return `<path d="M${l - 22},${y - 4} Q${l},${y - 22} ${l + 22},${y - 4}" fill="none" stroke="${color}" stroke-width="8" stroke-linecap="round"/><path d="M${r - 22},${y - 4} Q${r},${y - 22} ${r + 22},${y - 4}" fill="none" stroke="${color}" stroke-width="8" stroke-linecap="round"/>`;
  }
}

function nose(style, cx, y, skin) {
  const dark = adj(skin, -0.14);
  switch (style) {
    case "long":
      return `<path d="M${cx - 6},${y - 40} Q${cx - 16},${y + 8} ${cx - 24},${y + 22} Q${cx},${y + 36} ${cx + 24},${y + 22} Q${cx + 14},${y + 6} ${cx + 8},${y - 40}" fill="${dark}" ${st('stroke-width="6"')}/>`;
    case "button":
      return `<ellipse cx="${cx}" cy="${y + 8}" rx="15" ry="12" fill="${dark}" ${st('stroke-width="6"')}/>`;
    case "hook":
      return `<path d="M${cx - 4},${y - 34} Q${cx + 30},${y - 4} ${cx + 18},${y + 20} Q${cx},${y + 30} ${cx - 22},${y + 18} Q${cx - 6},${y + 10} ${cx - 8},${y - 6}Z" fill="${dark}" ${st('stroke-width="6"')}/>`;
    case "wide":
      return `<path d="M${cx - 34},${y + 14} Q${cx - 30},${y - 8} ${cx},${y - 10} Q${cx + 30},${y - 8} ${cx + 34},${y + 14} Q${cx},${y + 30} ${cx - 34},${y + 14}Z" fill="${dark}" ${st('stroke-width="6"')}/><circle cx="${cx - 12}" cy="${y + 16}" r="4" fill="${OUT}"/><circle cx="${cx + 12}" cy="${y + 16}" r="4" fill="${OUT}"/>`;
    default: // round bulb
      return `<ellipse cx="${cx}" cy="${y + 6}" rx="26" ry="22" fill="${dark}" ${st('stroke-width="6"')}/><ellipse cx="${cx - 8}" cy="${y - 2}" rx="7" ry="5" fill="#fff" opacity=".35"/>`;
  }
}

function mouth(style, cx, y) {
  const teeth = "#fffdf5", tongue = "#ff7a8a", cav = "#7a1630";
  switch (style) {
    case "grin":
      return `<path d="M${cx - 52},${y - 10} Q${cx},${y + 70} ${cx + 52},${y - 10} Q${cx},${y + 6} ${cx - 52},${y - 10}Z" fill="${cav}" ${st()}/><path d="M${cx - 46},${y - 6} Q${cx},${y + 8} ${cx + 46},${y - 6} L${cx + 40},${y + 14} Q${cx},${y + 24} ${cx - 40},${y + 14}Z" fill="${teeth}"/><ellipse cx="${cx}" cy="${y + 38}" rx="22" ry="10" fill="${tongue}"/><path d="M${cx - 52},${y - 10} Q${cx},${y + 70} ${cx + 52},${y - 10}" fill="none" ${st()}/>`;
    case "smirk":
      return `<path d="M${cx - 36},${y + 14} Q${cx + 8},${y + 30} ${cx + 44},${y - 12}" fill="none" ${st('stroke-width="9"')}/><path d="M${cx + 40},${y - 8} l10,-8" ${st('stroke-width="6"')}/>`;
    case "shout":
      return `<ellipse cx="${cx}" cy="${y + 20}" rx="34" ry="42" fill="${cav}" ${st()}/><path d="M${cx - 30},${y - 8} Q${cx},${y + 4} ${cx + 30},${y - 8} L${cx + 26},${y + 10} Q${cx},${y + 18} ${cx - 26},${y + 10}Z" fill="${teeth}"/><ellipse cx="${cx}" cy="${y + 46}" rx="22" ry="13" fill="${tongue}"/>`;
    case "oh":
      return `<ellipse cx="${cx}" cy="${y + 18}" rx="19" ry="26" fill="${cav}" ${st()}/><ellipse cx="${cx}" cy="${y + 28}" rx="11" ry="9" fill="${tongue}"/>`;
    case "tongue":
      return `<path d="M${cx - 44},${y - 2} Q${cx},${y + 40} ${cx + 44},${y - 2}" fill="none" ${st('stroke-width="8"')}/><path d="M${cx - 16},${y + 14} L${cx - 16},${y + 40} Q${cx},${y + 56} ${cx + 16},${y + 40} L${cx + 16},${y + 14}Z" fill="${tongue}" ${st('stroke-width="6"')}/><path d="M${cx},${y + 22} L${cx},${y + 40}" stroke="${adj(tongue, -0.3)}" stroke-width="4"/>`;
    case "gritted":
      return `<rect x="${cx - 44}" y="${y - 8}" width="88" height="34" rx="12" fill="${teeth}" ${st()}/><path d="M${cx - 22},${y - 8} v34 M${cx},${y - 8} v34 M${cx + 22},${y - 8} v34 M${cx - 44},${y + 9} h88" stroke="${OUT}" stroke-width="4"/>`;
    case "buck":
      return `<path d="M${cx - 40},${y} Q${cx},${y + 30} ${cx + 40},${y}" fill="none" ${st('stroke-width="8"')}/><rect x="${cx - 18}" y="${y + 4}" width="16" height="26" rx="4" fill="${teeth}" ${st('stroke-width="5"')}/><rect x="${cx + 2}" y="${y + 4}" width="16" height="26" rx="4" fill="${teeth}" ${st('stroke-width="5"')}/>`;
    default:
      return `<path d="M${cx - 34},${y} Q${cx},${y + 30} ${cx + 34},${y}" fill="none" ${st('stroke-width="8"')}/>`;
  }
}

function moustache(style, cx, y, color) {
  const f = `fill="${color}" ${st('stroke-width="5"')}`;
  switch (style) {
    case "handlebar":
      return `<path d="M${cx},${y - 6} Q${cx - 30},${y - 22} ${cx - 56},${y - 4} Q${cx - 74},${y + 10} ${cx - 62},${y - 24} Q${cx - 40},${y + 14} ${cx - 8},${y + 6} Z M${cx},${y - 6} Q${cx + 30},${y - 22} ${cx + 56},${y - 4} Q${cx + 74},${y + 10} ${cx + 62},${y - 24} Q${cx + 40},${y + 14} ${cx + 8},${y + 6} Z" ${f}/>`;
    case "thick":
      return `<path d="M${cx - 54},${y} Q${cx - 28},${y - 26} ${cx},${y - 10} Q${cx + 28},${y - 26} ${cx + 54},${y} Q${cx + 28},${y + 22} ${cx},${y + 6} Q${cx - 28},${y + 22} ${cx - 54},${y}Z" ${f}/>`;
    case "walrus":
      return `<path d="M${cx - 60},${y + 24} Q${cx - 50},${y - 22} ${cx},${y - 10} Q${cx + 50},${y - 22} ${cx + 60},${y + 24} Q${cx + 40},${y + 8} ${cx},${y + 8} Q${cx - 40},${y + 8} ${cx - 60},${y + 24}Z" ${f}/>`;
    case "pencil":
      return `<path d="M${cx - 44},${y + 2} Q${cx},${y - 16} ${cx + 44},${y + 2}" fill="none" stroke="${color}" stroke-width="9" stroke-linecap="round"/>`;
    default:
      return "";
  }
}

function beard(style, cx, cy, w, h, chin, color, skin) {
  const hp = headPath(cx, cy, w, h, chin);
  const l = cx - w / 2, r = cx + w / 2, y0 = cy + h * 0.0;
  // curved top edge: starts at the ears, dips toward the cheeks
  const lowerClip = `<clipPath id="lower"><path d="M0,${y0} L${l + 6},${y0} Q${cx - w * 0.28},${cy + h * 0.2} ${cx},${cy + h * 0.17} Q${cx + w * 0.28},${cy + h * 0.2} ${r - 6},${y0} L512,${y0} L512,600 L0,600Z"/></clipPath>`;
  switch (style) {
    case "full":
      return `${lowerClip}<clipPath id="hc2"><path d="${hp}"/></clipPath><g clip-path="url(#lower)"><path d="${hp}" fill="${color}"/></g><path d="${hp}" fill="none" ${st()}/><ellipse cx="${cx}" cy="${cy + h * 0.27}" rx="${w * 0.26}" ry="${h * 0.12}" fill="${skin}"/>`;
    case "goatee":
      return `<path d="M${cx - 40},${cy + h * 0.34} Q${cx},${cy + h * 0.62} ${cx + 40},${cy + h * 0.34} Q${cx},${cy + h * 0.4} ${cx - 40},${cy + h * 0.34}Z" fill="${color}" ${st('stroke-width="5"')}/><ellipse cx="${cx}" cy="${cy + h * 0.45}" rx="30" ry="22" fill="${color}"/>`;
    case "stubble":
      return `<linearGradient id="sg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity="0"/><stop offset="1" stop-color="${color}" stop-opacity=".42"/></linearGradient><clipPath id="hc3"><path d="${hp}"/></clipPath><g clip-path="url(#hc3)"><rect x="0" y="${cy + h * 0.02}" width="512" height="${h * 0.6}" fill="url(#sg)"/></g>`;
    case "chops":
      return `<path d="M${l + 4},${cy - h * 0.08} L${cx - w * 0.3},${cy + h * 0.3} L${l + w * 0.12},${cy + h * 0.12}Z" fill="${color}" ${st('stroke-width="4"')}/><path d="M${r - 4},${cy - h * 0.08} L${cx + w * 0.3},${cy + h * 0.3} L${r - w * 0.12},${cy + h * 0.12}Z" fill="${color}" ${st('stroke-width="4"')}/>`;
    case "soul":
      return `<ellipse cx="${cx}" cy="${cy + h * 0.4}" rx="12" ry="10" fill="${color}"/>`;
    default:
      return "";
  }
}

// ---- hair ------------------------------------------------------------------
function hairBack(style, cx, cy, w, h, color) {
  const t = cy - h / 2;
  if (style === "long")
    return `<path d="M${cx - w / 2 - 14},${cy - h * 0.1} C${cx - w / 2 - 40},${cy + h * 0.5} ${cx - w / 2 - 20},${cy + h * 0.75} ${cx - w / 2 + 10},${cy + h * 0.78} L${cx + w / 2 - 10},${cy + h * 0.78} C${cx + w / 2 + 20},${cy + h * 0.75} ${cx + w / 2 + 40},${cy + h * 0.5} ${cx + w / 2 + 14},${cy - h * 0.1} C${cx + w / 2},${t - 24} ${cx - w / 2},${t - 24} ${cx - w / 2 - 14},${cy - h * 0.1}Z" fill="${color}" ${st()}/>`;
  if (style === "afro")
    return Array.from({ length: 11 }, (_, i) => {
      const a = Math.PI * (1.02 + (i / 10) * 0.96);
      const x = cx + Math.cos(a) * (w * 0.6), y = cy - h * 0.06 + Math.sin(a) * (h * 0.58);
      return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="40" fill="${color}" ${st()}/>`;
    }).join("");
  if (style === "bun") return `<circle cx="${cx}" cy="${t - 30}" r="34" fill="${color}" ${st()}/>`;
  return "";
}

function hairFront(style, cx, cy, w, h, color) {
  const t = cy - h / 2, l = cx - w / 2, r = cx + w / 2;
  const crop = `M${l + 4},${cy - h * 0.08} C${l - 8},${t + 6} ${cx - w * 0.3},${t - 26} ${cx},${t - 26} C${cx + w * 0.3},${t - 26} ${r + 8},${t + 6} ${r - 4},${cy - h * 0.08} C${r - 8},${cy - h * 0.3} ${cx + w * 0.3},${cy - h * 0.27} ${cx},${cy - h * 0.31} C${cx - w * 0.3},${cy - h * 0.27} ${l + 8},${cy - h * 0.3} ${l + 4},${cy - h * 0.08}Z`;
  const f = `fill="${color}" ${st()}`;
  switch (style) {
    case "crop":
    case "long":
    case "bun":
      return `<path d="${crop}" ${f}/>`;
    case "spiky":
      return `<path d="${crop}" ${f}/>` + Array.from({ length: 7 }, (_, i) => {
        const x = l + 14 + i * ((w - 28) / 6);
        const hgt = 34 + (i % 2) * 22;
        return `<path d="M${x - 18},${t + 6} L${x},${t - 26 - hgt} L${x + 18},${t + 6}Z" ${f}/>`;
      }).join("");
    case "sidepart":
      return `<path d="${crop}" ${f}/><path d="M${l + 10},${cy - h * 0.2} C${cx - w * 0.2},${t - 10} ${cx + w * 0.1},${cy - h * 0.34} ${r - 6},${cy - h * 0.22} C${cx + w * 0.1},${cy - h * 0.3} ${cx - w * 0.2},${cy - h * 0.2} ${l + 10},${cy - h * 0.2}Z" ${f}/>`;
    case "afro":
      return `<path d="${crop}" ${f}/>`;
    case "mohawk":
      return `<path d="M${cx - 26},${t + 10} L${cx - 20},${t - 50} L${cx - 8},${t - 14} L${cx},${t - 62} L${cx + 10},${t - 14} L${cx + 22},${t - 52} L${cx + 28},${t + 10}Z" ${f}/>`;
    case "receding":
      return `<path d="M${l + 2},${cy - h * 0.05} C${l - 6},${t + 30} ${l + 14},${t + 10} ${l + 34},${t + 24} C${l + 26},${cy - h * 0.18} ${l + 22},${cy - h * 0.1} ${l + 22},${cy - h * 0.0}Z" ${f}/><path d="M${r - 2},${cy - h * 0.05} C${r + 6},${t + 30} ${r - 14},${t + 10} ${r - 34},${t + 24} C${r - 26},${cy - h * 0.18} ${r - 22},${cy - h * 0.1} ${r - 22},${cy - h * 0.0}Z" ${f}/>`;
    case "curly":
      return Array.from({ length: 7 }, (_, i) => {
        const x = l + 10 + i * ((w - 20) / 6), y = t + 2 - Math.sin((i / 6) * Math.PI) * 18;
        return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="27" ${f}/>`;
      }).join("");
    default:
      return "";
  }
}

// ---- headwear --------------------------------------------------------------
function headwear(kind, cx, cy, w, h, c, s) {
  const t = cy - h / 2, l = cx - w / 2, r = cx + w / 2, by = cy - h * 0.2;
  const dark = adj(c, -0.28);
  switch (kind) {
    case "cap":
      return `<path d="M${l - 6},${by + 6} C${l - 14},${t - 8} ${cx - w * 0.36},${t - 52} ${cx},${t - 54} C${cx + w * 0.36},${t - 52} ${r + 14},${t - 8} ${r + 6},${by + 6} Q${cx},${by - 12} ${l - 6},${by + 6}Z" fill="${c}" ${st()}/><path d="M${cx},${t - 54} L${cx},${by - 6}" stroke="${dark}" stroke-width="5" fill="none"/><circle cx="${cx}" cy="${t - 54}" r="8" fill="${dark}" ${st('stroke-width="5"')}/><path d="M${l + 4},${by + 2} Q${cx},${by + h * 0.12} ${r - 4},${by + 2} Q${cx + w * 0.25},${by + h * 0.2} ${cx},${by + h * 0.22} Q${cx - w * 0.25},${by + h * 0.2} ${l + 4},${by + 2}Z" fill="${dark}" ${st()}/>`;
    case "helmet":
      return `<path d="M${l - 12},${by + 14} C${l - 20},${t - 6} ${cx - w * 0.38},${t - 56} ${cx},${t - 58} C${cx + w * 0.38},${t - 56} ${r + 20},${t - 6} ${r + 12},${by + 14} Q${cx},${by - 6} ${l - 12},${by + 14}Z" fill="${c}" ${st()}/><path d="M${l - 12},${by + 8} L${l - 18},${cy + h * 0.2} Q${l + 6},${cy + h * 0.28} ${l + 26},${cy + h * 0.16} L${l + 20},${by + 20}Z" fill="${dark}" ${st('stroke-width="6"')}/><path d="M${r + 12},${by + 8} L${r + 18},${cy + h * 0.2} Q${r - 6},${cy + h * 0.28} ${r - 26},${cy + h * 0.16} L${r - 20},${by + 20}Z" fill="${dark}" ${st('stroke-width="6"')}/><path d="M${l + 2},${by + 10} Q${cx},${by + h * 0.14} ${r - 2},${by + 10} L${r - 6},${by + 30} Q${cx},${by + h * 0.2} ${l + 6},${by + 30}Z" fill="${dark}" ${st('stroke-width="6"')}/><path d="M${cx - 50},${t - 20} Q${cx},${t - 40} ${cx + 50},${t - 20}" fill="none" stroke="#fff" stroke-width="6" opacity=".35" stroke-linecap="round"/>`;
    case "bucket":
      return `<path d="M${l + 8},${by + 4} C${l},${t - 14} ${cx - w * 0.3},${t - 40} ${cx},${t - 42} C${cx + w * 0.3},${t - 40} ${r},${t - 14} ${r - 8},${by + 4}Z" fill="${c}" ${st()}/><path d="M${l - 38},${by + 18} Q${cx},${by - 18} ${r + 38},${by + 18} Q${cx},${by + 44} ${l - 38},${by + 18}Z" fill="${c}" ${st()}/><path d="M${l + 8},${by - 2} Q${cx},${by - 22} ${r - 8},${by - 2}" fill="none" stroke="${s.trim}" stroke-width="12"/>`;
    case "headband":
      return `<path d="M${l - 4},${by + 8} Q${cx},${by - 22} ${r + 4},${by + 8} L${r + 2},${by + 34} Q${cx},${by + 6} ${l - 2},${by + 34}Z" fill="${c}" ${st('stroke-width="6"')}/><path d="M${r - 8},${by + 14} l34,-16 l-6,34 Z" fill="${c}" ${st('stroke-width="5"')}/>`;
    case "bandana":
      return `<path d="M${l - 6},${by + 12} C${l - 14},${t - 4} ${cx - w * 0.36},${t - 40} ${cx},${t - 40} C${cx + w * 0.36},${t - 40} ${r + 14},${t - 4} ${r + 6},${by + 12} Q${cx},${by + 40} ${l - 6},${by + 12}Z" fill="${c}" ${st()}/><circle cx="${cx - 40}" cy="${t - 10}" r="6" fill="#fff" opacity=".7"/><circle cx="${cx + 10}" cy="${t - 26}" r="6" fill="#fff" opacity=".7"/><circle cx="${cx + 50}" cy="${t - 6}" r="6" fill="#fff" opacity=".7"/><path d="M${l - 4},${by + 20} l-34,10 l8,-30Z M${l - 4},${by + 24} l-26,34 l-6,-24Z" fill="${c}" ${st('stroke-width="5"')}/>`;
    default:
      return "";
  }
}

// ---- compose ---------------------------------------------------------------
export function characterSvg(s) {
  const cx = 256, cy = 228;
  const w = s.w, h = s.h;
  const skin = s.skin;
  const dark = adj(skin, -0.16);
  const eyeY = cy - h * 0.0, eyeDX = w * 0.215;
  const browY = eyeY - h * 0.16, noseY = cy + h * 0.06, mouthY = cy + h * 0.24;
  const earSize = s.ear || 1;

  const parts = [];
  parts.push(hairBack(s.hair, cx, cy, w, h, s.hairColor));
  parts.push(jersey(s));
  parts.push(`<path d="M${cx - 44},${cy + h * 0.38} L${cx - 46},${cy + h * 0.6} Q${cx},${cy + h * 0.74} ${cx + 46},${cy + h * 0.6} L${cx + 44},${cy + h * 0.38}Z" fill="${dark}" ${st()}/>`);
  // ears
  for (const sd of [-1, 1]) {
    const ex = cx + sd * (w / 2 - 2);
    parts.push(`<ellipse cx="${ex + sd * 6}" cy="${eyeY + 8}" rx="${20 * earSize}" ry="${30 * earSize}" fill="${skin}" ${st('stroke-width="6"')}/><ellipse cx="${ex + sd * 8}" cy="${eyeY + 10}" rx="${8 * earSize}" ry="${15 * earSize}" fill="${dark}" opacity=".55"/>`);
  }
  if (s.earring) parts.push(`<circle cx="${cx - w / 2 - 6}" cy="${eyeY + 44}" r="8" fill="#ffd34d" ${st('stroke-width="4"')}/>`);
  // head
  parts.push(`<clipPath id="hc"><path d="${headPath(cx, cy, w, h, s.chin)}"/></clipPath>`);
  parts.push(`<path d="${headPath(cx, cy, w, h, s.chin)}" fill="${skin}" ${st()}/>`);
  parts.push(`<g clip-path="url(#hc)"><ellipse cx="${cx + w * 0.42}" cy="${cy + h * 0.1}" rx="${w * 0.28}" ry="${h * 0.7}" fill="${dark}" opacity=".35"/><ellipse cx="${cx - w * 0.16}" cy="${cy - h * 0.3}" rx="${w * 0.16}" ry="${h * 0.07}" fill="#fff" opacity=".22"/></g>`);
  if (s.blush) parts.push(`<ellipse cx="${cx - w * 0.3}" cy="${cy + h * 0.14}" rx="22" ry="14" fill="#ff6b7a" opacity=".38"/><ellipse cx="${cx + w * 0.3}" cy="${cy + h * 0.14}" rx="22" ry="14" fill="#ff6b7a" opacity=".38"/>`);
  parts.push(beard(s.beard, cx, cy, w, h, s.chin, s.hairColor, skin));
  parts.push(mouth(s.mouth, cx, mouthY));
  parts.push(moustache(s.moustache, cx, mouthY - 22, s.hairColor));
  parts.push(nose(s.nose, cx, noseY, skin));
  if (s.zinc) parts.push(`<path d="M${cx - 20},${noseY - 6} Q${cx},${noseY - 22} ${cx + 20},${noseY - 6} L${cx + 16},${noseY + 6} Q${cx},${noseY - 6} ${cx - 16},${noseY + 6}Z" fill="#fff" opacity=".85"/>`);
  if (s.eyes === "shades") {
    parts.push(`<path d="M${cx - eyeDX - 36},${eyeY - 20} h72 a14,14 0 0 1 14,14 v14 a24,24 0 0 1 -24,24 h-38 a24,24 0 0 1 -24,-24 v-14 a14,14 0 0 1 0,-14Z" fill="#111" ${st('stroke-width="5"')}/>`);
    parts.push(`<path d="M${cx + eyeDX - 36},${eyeY - 20} h72 a14,14 0 0 1 14,14 v14 a24,24 0 0 1 -24,24 h-38 a24,24 0 0 1 -24,-24 v-14 a14,14 0 0 1 0,-14Z" fill="#111" ${st('stroke-width="5"')}/>`);
    parts.push(`<path d="M${cx - 12},${eyeY - 8} h24" ${st('stroke-width="6"')}/><path d="M${cx - eyeDX - 22},${eyeY - 12} l16,-4 M${cx + eyeDX - 22},${eyeY - 12} l16,-4" stroke="#fff" stroke-width="5" opacity=".6" stroke-linecap="round"/>`);
  } else {
    parts.push(eye(s.eyes, cx - eyeDX, eyeY, -1, s));
    parts.push(eye(s.eyes, cx + eyeDX, eyeY, 1, s));
  }
  parts.push(brows(s.brows, cx, browY, eyeDX, s.hairColor));
  if (s.mole) parts.push(`<circle cx="${cx + w * 0.26}" cy="${cy + h * 0.2}" r="5" fill="${OUT}"/>`);
  if (s.sweat) parts.push(`<path d="M${cx + w * 0.42},${cy - h * 0.3} q-18,30 0,42 q18,-12 0,-42Z" fill="#8fd6ff" ${st('stroke-width="4"')}/>`);
  if (s.hair !== "none") parts.push(hairFront(s.hair, cx, cy, w, h, s.hairColor));
  parts.push(headwear(s.headwear, cx, cy, w, h, s.hatColor, s));

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512"><g transform="translate(256 266) scale(1.1) translate(-256 -266)">${parts.join("")}</g></svg>`;
}
